const P = 'shreshthata/energy/';
let h = context.get('hour');
if (h === undefined) h = 5.75;          // start of simulation: 06:00
h = (h + 0.25) % 24;                     // each tick = 15 simulated minutes
context.set('hour', h);
return [ {payload: {hour: h}}, {topic: P + 'clock/hour', payload: h} ];

const P = 'shreshthata/energy/';
const h = msg.payload.hour;
let s = 0;
if (h > 6 && h < 18) s = 5 * Math.sin(Math.PI * (h - 6) / 12);   // 5 kW solar peak at noon
s = Math.max(0, s * (0.85 + Math.random() * 0.3));                // cloud noise
s = Math.round(s * 100) / 100;
return [[
  {topic: P + 'generation/solar_kw', payload: s},
  {topic: P + 'generation/bid', payload: {supply_kw: s, cost_per_kwh: 0}}
]];

const P = 'shreshthata/energy/';
const h = msg.payload.hour;
let d = 0.8
      + 1.8 * Math.exp(-Math.pow(h - 8, 2) / 2)     // morning peak
      + 0.6 * Math.exp(-Math.pow(h - 13, 2) / 4)    // lunch bump
      + 3.2 * Math.exp(-Math.pow(h - 20, 2) / 3);   // evening peak
d = Math.round(d * (0.9 + Math.random() * 0.2) * 100) / 100;
const flex = Math.round(d * 0.3 * 100) / 100;       // 30% of load can be shifted
return [[
  {topic: P + 'load/demand_kw', payload: d},
  {topic: P + 'load/bid', payload: {demand_kw: d, flexible_kw: flex}}
]];

const P = 'shreshthata/energy/';
const h = msg.payload.hour;
let p = 6;                                   // normal day tariff (Rs/kWh)
if (h >= 22 || h < 6) p = 4;                 // night: cheap
else if (h >= 18) p = 10;                    // evening: peak
const spike = Math.random() < 0.05 ? 3 : 0;  // random 5% price spike
p += spike;
return [[
  {topic: P + 'pricing/rate_per_kwh', payload: p},
  {topic: P + 'pricing/export_rate', payload: 3},
  {topic: P + 'pricing/bid', payload: {buy: p, sell: 3, spike: spike > 0}}
]];

const P = 'shreshthata/energy/';
const CAP = 10, MINP = 20, MAXP = 90, MAXKW = 3, EFF = 0.95, DT = 0.25;
let soc = context.get('soc');
if (soc === undefined) soc = 5;              // start at 50% of 10 kWh

// Command from the coordinator: remember it, apply it on the next tick
if (msg.topic && msg.topic.endsWith('agent/command')) {
    const c = msg.payload || {};
    context.set('pending', Number(c.battery_kw) || 0);
    return null;
}

// Clock tick: apply the last command (+ = charge, - = discharge)
const kw = context.get('pending') || 0;
const minE = CAP * MINP / 100, maxE = CAP * MAXP / 100;
if (kw > 0) {
    soc += Math.min(kw * DT * EFF, maxE - soc);
} else if (kw < 0) {
    soc -= Math.min(-kw * DT / EFF, Math.max(soc - minE, 0));
}
context.set('soc', soc);
context.set('pending', 0);

const socPct = Math.round(soc / CAP * 1000) / 10;
const maxCharge = Math.max(0, Math.min(MAXKW, (maxE - soc) / (DT * EFF)));
const maxDis = Math.max(0, Math.min(MAXKW, (soc - minE) * EFF / DT));
node.status({fill: 'blue', shape: 'dot', text: 'SoC ' + socPct + '%'});
return [[
  {topic: P + 'storage/soc_percent', payload: socPct},
  {topic: P + 'storage/bid', payload: {
      max_charge_kw: Math.round(maxCharge * 100) / 100,
      max_discharge_kw: Math.round(maxDis * 100) / 100,
      soc_percent: socPct}}
]];

const P = 'shreshthata/energy/';
const DT = 0.25, LOW = 4.5, HIGH = 8;
const r = v => Math.round(v * 100) / 100;
const s = flow.get('state') || {};
if ([s.solar, s.load, s.soc, s.price].some(v => v === undefined || isNaN(v))) {
    node.status({fill: 'yellow', shape: 'ring', text: 'waiting for agents'});
    return null;
}
const solar = s.solar, load = s.load, soc = s.soc, price = s.price;
const exp = (s.export === undefined || isNaN(s.export)) ? 3 : s.export;
const maxCh = (s.sbid && s.sbid.max_charge_kw) || 0;
const maxDis = (s.sbid && s.sbid.max_discharge_kw) || 0;
const flex = (s.lbid && s.lbid.flexible_kw) || 0;

let battery = 0, grid = 0, exportKw = 0, shift = 0, action = '', why = '';
const net = solar - load;

if (net >= 0) {
    // SURPLUS: store it, sell the rest
    const ch = Math.min(net, maxCh);
    battery = ch;
    exportKw = net - ch;
    if (ch > 0.05) {
        action = 'CHARGE BATTERY';
        why = 'solar surplus ' + r(net) + ' kW, storing ' + r(ch) + ' kW' +
              (exportKw > 0.05 ? ', exporting ' + r(exportKw) + ' kW' : '');
    } else {
        action = 'EXPORT TO GRID';
        why = 'surplus ' + r(net) + ' kW and battery cannot take more, selling at ₹' + exp + '/kWh';
    }
} else {
    // DEFICIT: decide by price
    let deficit = -net;
    if (price >= HIGH) {
        shift = Math.min(flex, deficit);
        deficit -= shift;
        const d = Math.min(deficit, maxDis);
        battery = -d;
        grid = deficit - d;
        const parts = [];
        if (shift > 0.05) parts.push('shift ' + r(shift) + ' kW flexible load to off-peak');
        if (d > 0.05) parts.push('discharge battery ' + r(d) + ' kW');
        if (grid > 0.05) parts.push('import ' + r(grid) + ' kW from grid');
        action = d > 0.05 ? 'DISCHARGE BATTERY' : (shift > 0.05 ? 'SHIFT LOAD' : 'IMPORT FROM GRID');
        why = 'peak price ₹' + price + '/kWh: ' + parts.join(', ');
    } else if (price <= LOW) {
        grid = deficit;
        if (soc < 70 && maxCh > 0.05) {
            const gc = Math.min(maxCh, 2);
            battery = gc;
            grid += gc;
            action = 'CHARGE FROM GRID';
            why = 'cheap tariff ₹' + price + '/kWh and SoC ' + soc + '%, charging ' + r(gc) + ' kW from grid';
        } else {
            action = 'IMPORT FROM GRID';
            why = 'cheap tariff ₹' + price + '/kWh, covering ' + r(deficit) + ' kW deficit from grid';
        }
    } else {
        if (soc > 50 && maxDis > 0.05) {
            const d = Math.min(deficit, maxDis);
            battery = -d;
            grid = deficit - d;
            action = 'DISCHARGE BATTERY';
            why = 'normal price ₹' + price + '/kWh, SoC ' + soc + '% is healthy, discharging ' + r(d) + ' kW';
        } else {
            grid = deficit;
            action = 'IMPORT FROM GRID';
            why = 'normal price ₹' + price + '/kWh, keeping battery for the peak, importing ' + r(deficit) + ' kW';
        }
    }
}

// Cost with agents vs a baseline (solar only, no battery, no coordination)
const base = Math.max(0, load - solar) * price * DT - Math.max(0, solar - load) * exp * DT;
const withSys = grid * price * DT - exportKw * exp * DT + shift * LOW * DT;
const sv = flow.get('sav') || {base: 0, withSys: 0};
sv.base += base;
sv.withSys += withSys;
flow.set('sav', sv);

battery = r(battery); grid = r(grid); exportKw = r(exportKw); shift = r(shift);
const hh = Math.floor(s.hour || 0), mm = Math.round(((s.hour || 0) - hh) * 60);
const clock = String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
const log = '[' + clock + '] Generation offers ' + solar + ' kW @ ₹0 | Load requests ' + load +
            ' kW (flexible ' + flex + ') | Storage: charge up to ' + maxCh + ' kW, discharge up to ' + maxDis +
            ' kW (SoC ' + soc + '%) | Price: buy ₹' + price + ', sell ₹' + exp + ' | DECISION: ' + action;

node.status({fill: 'green', shape: 'dot', text: action});
return [[
  {topic: P + 'agent/command', payload: {battery_kw: battery, grid_import_kw: grid, export_kw: exportKw, shift_kw: shift}},
  {topic: P + 'agent/recommendation', payload: action + ' - ' + why},
  {topic: P + 'agent/negotiation_log', payload: log},
  {topic: P + 'agent/savings', payload: {saved: r(sv.base - sv.withSys), baseline: r(sv.base), with_agents: r(sv.withSys)}}
]];

const P = 'shreshthata/energy/';
const t = msg.topic.replace(P, '');
const s = flow.get('state') || {};
const o = [null, null, null, null, null, null, null, null];
const num = Number(msg.payload);
switch (t) {
    case 'generation/solar_kw': s.solar = num; o[0] = {topic: 'Solar kW', payload: num}; break;
    case 'load/demand_kw': s.load = num; o[0] = {topic: 'Load kW', payload: num}; break;
    case 'storage/soc_percent': s.soc = num; o[1] = {payload: num}; break;
    case 'pricing/rate_per_kwh': s.price = num; o[2] = {payload: num}; break;
    case 'pricing/export_rate': s.export = num; break;
    case 'generation/bid': s.gbid = msg.payload; break;
    case 'load/bid': s.lbid = msg.payload; break;
    case 'storage/bid': s.sbid = msg.payload; break;
    case 'clock/hour': {
        s.hour = num;
        const hh = Math.floor(num), mm = Math.round((num - hh) * 60);
        o[3] = {payload: String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0')};
        break;
    }
    case 'agent/command': {
        const c = msg.payload || {};
        o[4] = [
          {topic: 'Battery kW (+charge / -discharge)', payload: c.battery_kw},
          {topic: 'Grid import kW', payload: c.grid_import_kw},
          {topic: 'Export kW', payload: c.export_kw}
        ];
        break;
    }
    case 'agent/recommendation': o[5] = {payload: msg.payload}; break;
    case 'agent/negotiation_log': o[6] = {payload: msg.payload}; break;
    case 'agent/savings': {
        const v = msg.payload || {};
        o[7] = {payload: '₹' + v.saved + ' saved (baseline ₹' + v.baseline + ' vs with agents ₹' + v.with_agents + ')'};
        break;
    }
}
flow.set('state', s);
return o;
